// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"satoshi":{"slug":"satoshi","cat":"basics","en":"Satoshi (sats)","contentLocale":"ja","term":"サトシ（sats）","aka":["sats","sat"],"short":"サトシ（sats）とは、ビットコインの最小単位で、1サトシは1億分の1 BTC（0.00000001 BTC）に相当します。","body":[["名前は",["ビットコイン","bitcoin"],"の考案者とされるサトシ・ナカモトに由来します。1 BTC = 100,000,000サトシなので、ビットコインの価格が高くなっても、サトシ単位で考えれば少額の購入や送金を直感的に扱えます。"],["一部の",["ウォレット","crypto-wallet"],"やライトニングネットワーク対応アプリでは、残高や送金額をサトシ単位で表示します。一方、取引所では通常BTC単位で表示されるため、小数点以下の桁数を読み間違えないよう注意が必要です。"],["「サトシを積み上げる（stack sats）」という言い方は、少額ずつビットコインを買い増すことを意味する海外の俗語です。",["積立投資","dollar-cost-averaging"],"やドルコスト平均法の話題でよく使われます。"]],"example":"例えば、1 BTC = 1,200万円のとき、1サトシは0.12円です。毎月6,000円分を買うと、受け取るのは6,000 ÷ 0.12 = 50,000サトシ（0.0005 BTC）です。価格が1,500万円になると1サトシは0.15円になり、同じ6,000円で買えるのは40,000サトシに減ります。価格が上がるほど、同じ金額で買えるサトシの量は少なくなるわけです。","mistakes":["0.0005 BTCと0.005 BTCのように、小数点以下の桁を一つ間違えて注文や送金をすること。","ウォレットの表示単位がサトシなのにBTCだと思い込み、残高を大きく読み違えること。","少額すぎる量を出金し、出金手数料が金額の大部分を占めてしまうこと。"],"faq":[{"q":"1サトシは何円ですか？","a":"ビットコインの円建て価格を1億で割った値です。例えば1 BTC = 1,000万円なら、1サトシは0.1円です。"},{"q":"サトシ単位でビットコインを買えますか？","a":"取引所の注文はBTC単位や円建ての金額で指定するのが一般的ですが、受け取る量はサトシ単位まで細かく分割されます。ただし取引所ごとに最小注文額があります。"}],"title":"サトシ（sats）とは？ビットコインの最小単位を解説","description":"ビットコインの最小単位サトシ（sats）の意味、円への換算方法、少額購入や積立での使われ方を具体例で解説します。","related":[["bitcoin","ビットコイン（BTC）","ビットコイン（BTC）とは、2009年に運用が始まった最初の暗号資産で、発行上限2100万枚、管理者のいないネットワークでプルーフ・オブ・ワークにより運営されています。"],["dollar-cost-averaging","ドルコスト平均法（DCA）","ドルコスト平均法（DCA）とは、価格に関係なく一定の金額を定期的に買い続けることで、購入タイミングを分散させる投資手法です。"],["market-order","成行注文","成行注文とは、価格を指定せずに、その時点で板にある最も有利な価格から順に、すぐに売買を成立させる注文方法です。"],["cryptocurrency","暗号資産（仮想通貨）","暗号資産（仮想通貨）とは、ブロックチェーンなどの技術で発行・管理され、インターネット上で個人間で直接やり取りできるデジタル資産のことです。"]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"ビットコイン一枚は高すぎる。それでも少しだけ買えますか？"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"fomo":{"slug":"fomo","cat":"basics","en":"FOMO","contentLocale":"ja","term":"FOMO（フォーモ）","aka":["フォーモ","取り残される恐怖"],"short":"FOMOとは「Fear Of Missing Out」の略で、値上がりに乗り遅れることへの不安から、冷静な判断をせずに買ってしまう心理のことです。","body":[[["暗号資産","cryptocurrency"],"では、SNSで「〇倍になった」という投稿が拡散されたり、価格が短時間で急騰したりすると、FOMOが起こりやすくなります。急いで買った結果、上昇の終盤で高値をつかみ、その後の調整で損失を抱えるのが典型的なパターンです。"],["FOMOによる取引には、計画がない、ポジションが大きすぎる、",["損切り","stop-loss"],"の基準がない、という共通点があります。さらに",["レバレッジ","leverage"],"を使うと、少し逆に動いただけで",["強制ロスカット","liquidation"],"される危険が高まります。"],"対策は、事前にルールを決めておくことです。1回の取引で失ってよい金額を総資金の1〜2%などに決め、エントリー価格、損切り価格、利益確定の目安を注文前に書き出します。急騰中の銘柄を見たときに、成行ですぐ買わず指値で待つだけでも、衝動的な取引を減らせます。"],"example":"例えば、1時間で1ドルから1.4ドルへ40%上がったコインを、1.4ドルで1,000ドル分買ったとします。その後、上昇分の半分が戻って1.2ドルになると、評価額は約857ドルで、約143ドルの損失です。もし最初から1回の損失上限を総資金5,000ドルの2%（100ドル）と決めていれば、ポジションをもっと小さくするか、エントリーを見送る判断ができたはずです。","mistakes":["急騰しているチャートだけを見て、成行で一気に買うこと。","乗り遅れた分を取り戻そうとして、レバレッジを高くすること。","損切りの基準を決めずに買い、下がってから判断を先延ばしにすること。"],"faq":[{"q":"FOMOとFUDの違いは何ですか？","a":"FOMOは乗り遅れへの恐怖から買いに走る心理で、FUDは恐怖や不安、疑念をあおる情報によって売りに傾く状況を指します。"},{"q":"FOMOを防ぐにはどうすればいいですか？","a":"取引前にエントリー、損切り、ポジションサイズを決めておき、ルールに合わない取引はしないことが有効です。"}],"title":"FOMOとは？意味と投資で失敗しないための対策","description":"暗号資産でよく使われるFOMOの意味、高値づかみが起こる理由、衝動的な取引を防ぐための具体的な対策を解説します。","related":[["fud","FUD（ファッド）","FUDとは「Fear, Uncertainty and Doubt（恐怖・不確実性・疑念）」の略で、市場に不安を広げ、売りを誘うような情報や雰囲気のことです。"],["bull-market","強気相場（ブルマーケット）","強気相場（ブルマーケット）とは、価格が長期間にわたって上昇傾向を続け、市場参加者の間に楽観的な見方が広がっている相場のことです。"],["position-sizing","ポジションサイジング（建玉管理）","ポジションサイジングとは、1回の取引でどれだけの数量を建てるかを、許容できる損失額と損切りまでの距離から逆算して決める資金管理の方法です。"],["fear-and-greed-index","恐怖・強欲指数（Fear and Greed Index）","恐怖・強欲指数とは、価格変動率や出来高、SNSの反応などを組み合わせて、市場参加者の心理を0（極度の恐怖）から100（極度の強欲）の数値で表した指標です。"],["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"いくら買うか決める前に、いくら失えるかを決めよ"},"coin":null,"tool":null,"cta":false},"wash-trading":{"slug":"wash-trading","cat":"trading","en":"Wash trading","contentLocale":"ja","term":"ウォッシュトレード（仮装売買）","aka":["仮装売買","ウォッシュトレーディング","wash trading"],"short":"ウォッシュトレード（仮装売買）とは、同じ人物や協力関係にある者同士が自分で買って自分で売り、実態のない取引を作って取引量や価格を偽装する行為です。","body":[["ウォッシュトレードでは、売り手と買い手が実質的に同一なので、資産の持ち主は変わりません。それでも約定記録は残るため、",["取引量","trading-volume"],"が増え、人気がある銘柄のように見えます。目的は、取引所のランキングを上げる、",["上場","token-listing"],"直後のトークンを活発に見せる、NFTの取引履歴に高値を付ける、取引量に応じた報酬や",["エアドロップ","airdrop"],"を得る、などさまざまです。"],["株式市場など多くの法域では仮装売買は相場操縦として禁止されています。",["暗号資産","cryptocurrency"],"でも規制は強まっていますが、国や取引所によって監視体制は異なります。日本の",["暗号資産交換業者","vasp"],"は金融商品取引法の不公正取引規制の対象です。"],["読者として大切なのは、見せかけの取引量に惑わされないことです。取引量に比べて板が極端に薄い、同じ数量の約定が規則的に繰り返される、取引量が多いのに",["スプレッド","bid-ask-spread"],"が広い、といった点は疑うきっかけになります。"]],"example":"ある新規トークンの24時間取引量が500万 USDTと表示されているのに、現在値から±2%以内の板には買いと売りを合わせて1万 USDT分しか注文がないとします。本当に500万 USDTの売買があれば、板はもっと厚くなるのが普通です。試しに3,000 USDT分を成行で買うと、板の片側の半分以上を食い、価格が1%以上動いてしまいます。この食い違いは、取引量の多くが仮装売買である可能性を示すサインです。","mistakes":["取引量ランキングの上位にあるだけで、その銘柄や取引所に十分な流動性があると判断する。","NFTの過去の約定価格を、実際の需要を反映した相場だと信じて高値で買う。","自分で口座を2つ使って売買を繰り返し、取引量キャンペーンの報酬を狙う行為が規約違反や不正取引になり得ることを知らない。"],"faq":[{"q":"ウォッシュトレードは違法ですか？","a":"株式などでは多くの国で相場操縦として禁止されており、暗号資産でも規制対象とする法域が増えています。取り扱いは国によって異なり、取引所の規約でも禁止されているのが一般的です。"},{"q":"仮装売買を見抜く方法はありますか？","a":"取引量に対して板が薄くないか、スプレッドが広くないか、同じ数量の約定が機械的に続いていないかを確認します。複数の取引所の数字を比べるのも有効です。"}],"title":"ウォッシュトレード（仮装売買）とは？見抜き方","description":"ウォッシュトレード（仮装売買）の仕組みと目的、見せかけの取引量を見抜くために板やスプレッドで確認すべきポイントを解説します。","related":[["trading-volume","取引量（出来高）","取引量（出来高）とは、一定期間に実際に売買が成立した暗号資産の数量や金額の合計のことで、一般には24時間の値が使われます。"],["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["proof-of-reserves","準備金証明（プルーフ・オブ・リザーブ）","準備金証明（PoR）とは、取引所が利用者から預かった暗号資産と同額以上の資産を実際に保有していることを、ブロックチェーン上のデータなどで示す仕組みです。"],["market-maker","マーケットメイカー（MM）","マーケットメイカーとは、買い注文と売り注文の両方を板に出し続けて、他の参加者がいつでも売買できる状態を作る事業者やトレーダーのことです。"]],"lesson":null,"coin":null,"tool":"/exchanges","cta":false},"whale":{"slug":"whale","cat":"trading","en":"Whale","contentLocale":"ja","term":"クジラ（大口投資家）","aka":["クジラ","大口","ホエール","whale"],"short":"クジラとは、特定の暗号資産を大量に保有し、その売買や送金が市場価格に影響を与えるほどの規模を持つ大口の投資家やアドレスのことです。","body":[["クジラには、早くから保有している個人、ファンド、取引所、プロジェクトの運営チーム、",["マーケットメイカー","market-maker"],"などが含まれます。何枚以上でクジラと呼ぶかに決まった基準はなく、BTCなら1,000 BTC以上の",["アドレス","wallet-address"],"を目安にする分析サービスもあります。"],[["ブロックチェーン","blockchain"],"上の送金は誰でも見られるため、大口の送金を監視するサービスやアラートがあります。クジラが取引所へ大量のコインを送ると売り圧力の兆しと見られ、取引所から引き出すと長期保有の兆しと見られることがあります。ただし、取引所の",["ウォレット","crypto-wallet"],"間の移動やカストディ業者の整理であることも多く、一つの送金だけで意図を判断するのは危険です。"],[["流動性","liquidity"],"が薄い銘柄ほど、クジラの一度の売買で価格が大きく動きます。保有が少数のアドレスに集中しているトークンは、大口が売ったときの下落リスクが大きいため、上位保有者の割合を確認する習慣をつけるとよいでしょう。"]],"example":"あるトークンの総供給量が1億枚で、上位5アドレスが合計4,000万枚（40%）を持っているとします。そのうち1つのアドレスが500万枚を取引所に入金したというアラートが出ました。板には現在値の−5%以内に買い注文が200万枚分しかない場合、500万枚を一度に成行で売れば、板を何段も食って価格は5%以上下がる計算になります。ただし、実際に売るか、分割して売るかはわかりません。","mistakes":["クジラの送金アラートが出るたびに、すぐ売買の判断をしてしまう。","取引所のホットウォレットとコールドウォレット間の移動を、クジラの売りだと誤解する。","上位保有者への集中度を確認せずに小型トークンを買う。"],"faq":[{"q":"クジラの動きはどうやって確認できますか？","a":"ブロックエクスプローラーやオンチェーン分析サービスで、大口アドレスの残高や送金履歴を確認できます。取引所への入出金量の推移もよく使われる指標です。"},{"q":"クジラが取引所に送金したら価格は下がりますか？","a":"売り圧力の兆しと見られることはありますが、必ず下がるわけではありません。担保の差し入れや内部の資金移動など、別の目的であることも多いです。"}],"title":"クジラとは？暗号資産の大口投資家の意味","description":"暗号資産のクジラ（大口投資家）の意味、オンチェーンでの動きの見方、取引所への送金をどう読むか、注意点を具体例で解説します。","related":[["on-chain-analysis","オンチェーン分析","オンチェーン分析とは、ブロックチェーン上に公開されている取引記録やアドレスの残高などのデータを集計し、資金の流れや市場参加者の行動を読み解く手法のことです。"],["exchange-netflow","取引所ネットフロー（取引所への流入・流出）","取引所ネットフローとは、一定期間に暗号資産取引所のウォレットへ入った量から出た量を差し引いた数値で、流入超か流出超かを示すオンチェーン指標です。"],["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"margin-call":{"slug":"margin-call","cat":"derivatives","en":"Margin call","contentLocale":"ja","term":"マージンコール（追証）","aka":["追証","追加証拠金","証拠金維持率アラート","margin call"],"short":"マージンコールとは、損失によって証拠金が一定の水準を下回ったときに、取引所が追加の入金やポジションの縮小を求める警告や通知のことです。","body":[["伝統的な証券取引では、マージンコールを受けると期限までに追加の証拠金（追証）を入れなければなりません。",["暗号資産","cryptocurrency"],"取引所では仕組みが少し違い、多くの場合は警告の通知を出すだけで、実際には証拠金が",["維持証拠金","maintenance-margin"],"を下回った時点で自動的に",["強制ロスカット","liquidation"],"が行われます。期限を待ってくれるわけではありません。"],"取引所によって、証拠金維持率がある水準に達したときにメールやアプリで通知する機能があります。通知の基準やタイミングは取引所ごとに異なり、相場が急変すると通知が届く前に清算されることもあります。国内の業者では、証拠金維持率が一定以下になると追証が発生するルールを設けているところもあります。",["マージンコールを受けたときの選択肢は、証拠金を追加する、ポジションの一部を決済する、",["損切り","stop-loss"],"して撤退する、の3つです。追加入金で耐えるのは、相場がさらに逆行すれば損失を広げるだけになることもあります。"]],"example":[["クロスマージン","cross-margin"],"口座に2,000 USDTがあり、想定元本40,000 USDTのポジションの維持証拠金が400 USDTだとします。取引所の設定で、証拠金残高が維持証拠金の125%にあたる500 USDTを下回ると通知が届くとします。",["含み損","unrealized-pnl"],"が1,500 USDTに達して残高が500 USDTになったところで通知が来ます。そこからさらに100 USDT損失が増えれば、残高は400 USDTになり清算が始まります。"],"mistakes":["暗号資産取引所でも追証の通知後に入金の猶予期間があると思い込む。","通知を待ってから対処しようとして、急変時に通知より先に清算される。","マージンコールのたびに追加入金を繰り返し、損失を大きく広げる。"],"faq":[{"q":"マージンコールと強制ロスカットの違いは何ですか？","a":"マージンコールは証拠金不足の警告、強制ロスカットは実際にポジションが決済されることです。暗号資産取引所では警告からロスカットまでの猶予がほとんどない場合があります。"},{"q":"マージンコールを受けたらどうすればよいですか？","a":"証拠金を追加するか、ポジションを減らすか、損切りするかを判断します。追加入金は損失をさらに広げる可能性もあるため、事前に決めた損切りルールを優先してください。"}],"title":"マージンコール（追証）とは？暗号資産での仕組み","description":"マージンコール（追証）の意味、暗号資産取引所での通知と強制ロスカットの関係、警告を受けたときの対処法を具体例で解説します。","related":[["maintenance-margin","維持証拠金（メンテナンスマージン）","維持証拠金（メンテナンスマージン）とは、ポジションを持ち続けるために口座に残しておかなければならない最低限の証拠金で、これを下回ると強制ロスカット（清算）が始まります。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"],["cross-margin","クロスマージン","クロスマージンとは、口座内の利用可能な証拠金をすべてのポジションで共有する方式で、清算を遠ざけやすい一方、損失が口座全体に及ぶ可能性があります。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"証拠金がゼロになる前に強制終了されるのはなぜか"},"coin":null,"tool":"/liquidations","cta":false},"liquidation":{"slug":"liquidation","cat":"derivatives","en":"Liquidation","contentLocale":"ja","term":"強制ロスカット（清算）","aka":["清算","ロスカット","強制決済","リクイデーション"],"short":"強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。","body":[[["証拠金取引","margin-trading"],"や",["先物取引","futures-contract"],"では、借りた資金や",["レバレッジ","leverage"],"で大きなポジションを持っています。損失が証拠金を超えてしまうと取引所や他の参加者に損害が出るため、その前に取引所がポジションを自動で決済します。判定には通常、",["最終取引価格","last-price"],"ではなく",["マーク価格","mark-price"],"が使われます。"],["清算されると、そのポジションに割り当てた証拠金の大部分、または全部を失います。",["分離マージン","isolated-margin"],"ならそのポジションの証拠金だけ、クロスマージンなら口座全体の証拠金が対象になります。取引所によっては清算手数料がかかったり、残った証拠金が保険基金に入ったりします。"],"相場が急変すると、清算された注文が成行で市場に出て価格をさらに動かし、次の清算を呼ぶ連鎖が起きます。清算の結果、証拠金以上の損失が出た場合は保険基金で補われ、それでも足りないと自動デレバレッジ（ADL）が発動します。清算を避ける最善の方法は、清算価格より手前に損切りを置き、無理のないレバレッジにすることです。"],"example":"分離マージンで、ETHが2,400 USDTのときに証拠金240 USDTで1 ETHを10倍ロングしたとします。維持証拠金率が0.5%なら、手数料を無視すると清算価格は約2,171 USDTで、建値から約9.5%の下落です。ETHが2,170 USDTまで下がると、マーク価格が清算価格に達した時点でポジションは強制決済され、240 USDTのほぼすべてを失います。2,250 USDTに損切りを置いていれば、損失は150 USDTで済みました。","mistakes":["清算価格を確認せずにエントリーし、思ったより早くポジションを失う。","損切りを置かずに清算を事実上の損切りとして使い、証拠金全額を失う。","含み損が出るたびに証拠金を追加して清算を先延ばしにし、損失を大きくする。"],"faq":[{"q":"強制ロスカットされると借金になりますか？","a":"多くの暗号資産取引所では、清算で失うのは証拠金の範囲までで、不足分は保険基金などで補われます。ただし取引所や国内業者のルールによって扱いが異なるため確認してください。"},{"q":"清算と損切りの違いは何ですか？","a":"損切りは自分で決めた価格で損失を確定する決済、清算は証拠金不足で取引所が強制的に行う決済です。清算のほうが損失が大きく、手数料がかかることもあります。"}],"title":"強制ロスカット（清算）とは？仕組みと避け方","description":"強制ロスカット（清算）が起きる仕組み、維持証拠金とマーク価格の関係、連鎖清算、清算を避けるための損切りの置き方を解説します。","related":[["liquidation-price","清算価格（ロスカット価格）","清算価格（ロスカット価格）とは、マーク価格がその水準に達するとポジションが強制ロスカットされる価格のことで、レバレッジと維持証拠金率によって決まります。"],["maintenance-margin","維持証拠金（メンテナンスマージン）","維持証拠金（メンテナンスマージン）とは、ポジションを持ち続けるために口座に残しておかなければならない最低限の証拠金で、これを下回ると強制ロスカット（清算）が始まります。"],["mark-price","マーク価格","マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。"],["insurance-fund","保険基金（インシュアランスファンド）","保険基金とは、先物取引所が強制ロスカットで証拠金を超える損失が出たときの穴埋めに使うために積み立てている資金で、自動デレバレッジの発動を防ぐ役割を持ちます。"],["auto-deleveraging","自動デレバレッジ（ADL）","自動デレバレッジ（ADL）とは、清算されたポジションの損失を保険基金で補いきれないときに、反対側で利益が出ているトレーダーのポジションを取引所が強制的に縮小する仕組みです。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"強制決済（清算）：強制終了のボタンを押したのは誰か"},"coin":null,"tool":"/liquidations","cta":false},"liquidation-price":{"slug":"liquidation-price","cat":"derivatives","en":"Liquidation price","contentLocale":"ja","term":"清算価格（ロスカット価格）","aka":["ロスカット価格","強制決済価格","liquidation price"],"short":"清算価格（ロスカット価格）とは、マーク価格がその水準に達するとポジションが強制ロスカットされる価格のことで、レバレッジと維持証拠金率によって決まります。","body":[["清算価格は、ポジションの証拠金残高が",["維持証拠金","maintenance-margin"],"とちょうど等しくなる価格です。",["ロング","long-and-short"],"なら建値より下、ショートなら建値より上にあります。",["レバレッジ","leverage"],"が高いほど",["当初証拠金","initial-margin"],"が少なくなり、清算価格は建値に近づきます。"],[["分離マージン","isolated-margin"],"では、そのポジションの証拠金だけで計算されるため、清算価格は比較的はっきり決まります。",["クロスマージン","cross-margin"],"では口座全体の残高が使われるため、他のポジションの損益や残高の増減によって清算価格が変わり続けます。どちらの場合も、取引所の注文画面やポジション画面に表示される値を確認するのが確実です。"],"清算価格の計算には、維持証拠金率のほか、手数料や資金調達率の支払いが影響します。資金調達率を払い続けると証拠金が減り、清算価格は少しずつ建値に近づきます。証拠金を追加すれば清算価格を遠ざけられます。"],"example":"ETHが3,000 USDTのときに、分離マージン・10倍で2 ETHをショートし、証拠金600 USDTを入れたとします。維持証拠金率0.5%で手数料を無視すると、清算価格Pは、600−（P−3,000）×2＝0.005×2×P を解いて、P＝約3,284 USDTです。建値から約9.5%上昇すると清算されます。同じ条件で20倍にすると証拠金は300 USDTになり、清算価格は約3,134 USDTまで近づきます。","mistakes":["清算価格は建値からちょうどレバレッジ分の1動いた価格だと考え、維持証拠金の分を見落とす。","クロスマージンで表示された清算価格が、他のポジションの損益によって変わり続けることを知らない。","資金調達率の支払いで証拠金が減り、清算価格が徐々に近づくことに気づかない。"],"faq":[{"q":"清算価格はどうやって確認できますか？","a":"注文前は取引画面の計算ツールや注文確認に、保有中はポジション画面に表示されます。取引所によって計算方式が少し違うため、画面の値を基準にしてください。"},{"q":"清算価格を遠ざける方法はありますか？","a":"証拠金を追加するか、レバレッジを下げるか、ポジションの一部を決済する方法があります。"}],"title":"清算価格（ロスカット価格）とは？計算方法と確認方法","description":"清算価格（ロスカット価格）の意味、レバレッジと維持証拠金率から計算する方法、分離とクロスでの違いを具体例で解説します。","related":[["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"],["isolated-margin","分離マージン（アイソレーテッドマージン）","分離マージンとは、ポジションごとに証拠金を割り当てて管理する方式で、そのポジションが清算されても失うのは割り当てた証拠金だけに限られます。"],["mark-price","マーク価格","マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。"],["maintenance-margin","維持証拠金（メンテナンスマージン）","維持証拠金（メンテナンスマージン）とは、ポジションを持ち続けるために口座に残しておかなければならない最低限の証拠金で、これを下回ると強制ロスカット（清算）が始まります。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"強制決済（清算）：強制終了のボタンを押したのは誰か"},"coin":null,"tool":"/liquidations","cta":false},"long-short-ratio":{"slug":"long-short-ratio","cat":"derivatives","en":"Long/short ratio","contentLocale":"ja","term":"ロングショート比率","aka":["ロング・ショート比率","LSレシオ","ロングショートレシオ","long/short ratio"],"short":"ロングショート比率とは、先物市場でロング（買い）を持っている口座やポジションと、ショート（売り）を持っているものの割合を比べた指標で、市場参加者の偏りを見るのに使われます。","body":[["ロングショート比率は、",["ロング","long-and-short"],"の量をショートの量で割った値で表します。1より大きければロングが多く、1より小さければショートが多い状態です。取引所によって、口座数で数えるもの、ポジション量で数えるもの、上位トレーダーだけを対象にしたものなど、いくつかの種類があります。"],["注意したいのは、先物市場全体ではロングとショートの量は常に等しいという点です。",["建玉","open-interest"],"の1枚には必ず買い手と売り手がいます。そのため比率が2.0でも、それは「ロングを持つ口座の数がショートの2倍」という意味で、少数の大口がショートを持っている可能性があります。"],["比率が極端に偏ると、逆方向への急変が起きやすいと考える人もいます。例えばロングが多すぎると、下落時にロングの清算が連鎖しやすくなります。ただし比率だけで価格の方向は決まらないため、",["資金調達率","funding-rate"],"や建玉とあわせて見るのが一般的です。"]],"example":"ある取引所のBTC先物で、口座ベースのロングショート比率が2.0だとします。ロングの口座が全体の約66.7%、ショートの口座が約33.3%という意味です。一方、同じ時点のポジション量ベースの比率が0.9なら、ショート側の口座は数が少なくても1口座あたりの量が大きいと読めます。口座数では強気が多く見えても、資金の量ではショートがやや上回っていることになります。","mistakes":["口座ベースの比率を、市場全体のロングとショートの量の比だと誤解する。","比率が高いから必ず下がる、低いから必ず上がると決めつけて逆張りする。","取引所ごとに計算方法が違う比率を、そのまま比べる。"],"faq":[{"q":"ロングショート比率が高いとどういう意味ですか？","a":"ロングを持っている口座やポジションが多いという意味です。偏りが強いと、反対方向への急変時に清算が連鎖しやすくなると考えられています。"},{"q":"ロングとショートの量は本当は同じなのですか？","a":"先物の建玉では、ロング1枚に対して必ずショート1枚があるため、量の合計は同じです。比率は口座数や一部のトレーダーの偏りを表しています。"}],"title":"ロングショート比率とは？見方と注意点","description":"ロングショート比率の意味、口座ベースとポジションベースの違い、市場の偏りの読み方と使うときの注意点を具体例で解説します。","related":[["open-interest","建玉（未決済建玉・オープンインタレスト）","建玉（オープンインタレスト）とは、先物やオプションで、まだ決済されずに残っている契約の総数（または総額）のことで、市場にどれだけの資金がポジションとして入っているかを示します。"],["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"],["long-and-short","ロングとショート（買いポジション・売りポジション）","ロングとショートとは、価格の上昇で利益が出る買いのポジション（ロング）と、価格の下落で利益が出る売りのポジション（ショート）のことです。"],["short-squeeze","ショートスクイーズ（踏み上げ）","ショートスクイーズ（踏み上げ）とは、価格の上昇によってショートを持つ人が損切りや強制ロスカットで一斉に買い戻し、その買いがさらに価格を押し上げる現象です。"]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"anti-phishing-code":{"slug":"anti-phishing-code","cat":"wallets-security","en":"Anti-phishing code","contentLocale":"ja","term":"フィッシング対策コード","aka":["アンチフィッシングコード","anti-phishing code","なりすまし防止コード"],"short":"フィッシング対策コードとは、取引所から届く正規のメールに利用者が設定した合言葉を表示させ、偽メールと見分けやすくする機能です。","body":["多くの海外取引所では、セキュリティ設定から好きな文字列をフィッシング対策コードとして登録できます。登録後は、その取引所から届く正規のメールに、必ずあなたのコードが記載されるようになります。","偽メールの送り主はあなたのコードを知らないため、コードがない、または違うメールは偽物だと判断できます。ロゴや差出人名、文面がそっくりでも、コードの有無で見分けられるのが利点です。","ただし、すべての経路を守るわけではありません。SMS、SNSのDM、検索広告の偽サイトにはコードが表示されないため、メール以外の連絡は別途疑ってかかる必要があります。取引所によっては、ログイン画面や出金画面にもコードを表示する設定があります。"],"example":"あなたがフィッシング対策コードに「ume2026」と設定したとします。後日「出金が保留されました。24時間以内に確認してください」というメールが届きました。本文を探してもume2026の記載がなく、リンク先のドメインも公式と1文字違いでした。この時点で偽メールと判断し、リンクは開かず、ブックマークした公式サイトから直接ログインして状況を確認します。","mistakes":["パスワードや誕生日など、推測されやすい文字列をコードに設定すること。","コードを設定しただけで満足し、届いたメールでコードを確認する習慣がないこと。","SMSやSNSで届いた連絡も、コードがないのに正規だと思い込むこと。"],"faq":[{"q":"フィッシング対策コードは他人に知られても大丈夫ですか？","a":"知られると、偽メールにそのコードを入れられてしまい、見分ける効果がなくなります。他人に教えず、SNSなどにも載せないでください。"},{"q":"コードが入ったメールなら、リンクを開いても安全ですか？","a":"正規メールである可能性は高まりますが、リンクよりもブックマークや公式アプリからアクセスする方が安全です。習慣として公式経路を使いましょう。"}],"title":"フィッシング対策コードとは？設定方法と使い方","description":"取引所のフィッシング対策コードの意味、偽メールを見分ける仕組み、メール以外の詐欺には効かない点など正しい使い方を解説します。","related":[["phishing","フィッシング詐欺","フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。"],["two-factor-authentication","二段階認証（2FA）","二段階認証（2FA）とは、パスワードに加えて認証アプリのコードやセキュリティキーなど別の要素を求めることで、不正ログインを防ぐ仕組みです。"],["withdrawal-whitelist","出金ホワイトリスト","出金ホワイトリストとは、あらかじめ登録した送金先アドレスにだけ出金できるよう制限する取引所のセキュリティ機能です。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"本物の扉を見極める：やみくもに口座開設しないこと"},"coin":null,"tool":null,"cta":false},"pig-butchering-scam":{"slug":"pig-butchering-scam","cat":"wallets-security","en":"Pig-butchering scam","contentLocale":"ja","term":"豚の屠殺詐欺（ピッグブッチャリング）","aka":["ピッグブッチャリング詐欺","ロマンス投資詐欺","pig butchering","殺猪盤"],"short":"豚の屠殺詐欺とは、SNSやマッチングアプリで時間をかけて信頼関係を築いた後、偽の投資サイトやアプリに暗号資産を送金させてだまし取る詐欺です。","body":["名前は「豚を太らせてから屠る」という比喩に由来します。犯人は間違い電話やSNSのメッセージ、マッチングアプリで近づき、数週間から数か月かけて友人や恋人として信頼を得ます。",["その後「自分は",["暗号資産","cryptocurrency"],"で稼いでいる」と話し、特定の投資サイトやアプリを勧めます。最初は少額の出金を認めて利益が出ているように見せ、追加入金を促します。画面上の残高は作られた数字にすぎません。"],"大きな金額を出金しようとすると、「税金」「手数料」「保証金」などの名目でさらに送金を求められます。払っても出金はできません。会ったことのない相手が勧める投資先は、どれだけ親しくても疑ってください。"],"example":"ある人が知り合ったばかりの相手に勧められ、聞いたことのない取引サイトに10万円分のUSDTを入金したとします。数日で残高が13万円に増え、試しに2万円を出金すると実際に届きました。安心して200万円を追加入金し、残高が300万円になったところで出金を申請すると、「税金として残高の20%、60万円を先に払う必要がある」と言われます。この時点で、入金した210万円はすでに取り戻せない状態です。","mistakes":["少額の出金ができたことを、サイトが本物である証拠だと考えること。","出金のための「税金」や「保証金」を追加で送金してしまうこと。","相手から勧められたアプリやリンクを、公式ストアや金融当局の登録で確認しないこと。"],"faq":[{"q":"被害に遭ったらまず何をすべきですか？","a":"それ以上送金せず、相手とのやり取り、送金記録、TxIDを保存し、警察や消費生活センターなどの相談窓口に連絡してください。「資金を取り戻せる」とうたう業者は二次被害の詐欺であることが多いです。"},{"q":"どうすれば詐欺サイトだと見分けられますか？","a":"金融当局への登録の有無、公式アプリストアでの配信、運営会社の実在性を確認します。会ったことのない人が勧める投資先という時点で、強く疑うべきです。"}],"title":"豚の屠殺詐欺（ピッグブッチャリング）とは？手口と対策","description":"SNSやマッチングアプリから始まる豚の屠殺詐欺（ピッグブッチャリング）の手口、偽投資サイトの特徴、被害時の対処法を解説します。","related":[["phishing","フィッシング詐欺","フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。"],["rug-pull","ラグプル","ラグプルとは、暗号資産プロジェクトの開発者が流動性や集めた資金を突然引き揚げ、トークンの価格をほぼゼロにして投資家に損失を負わせる詐欺的な行為です。"],["p2p-trading","P2P取引（個人間取引）","P2P取引とは、取引所が仲介役となり、利用者同士が銀行振込などの法定通貨とUSDTなどの暗号資産を直接交換する取引方法です。"],["seed-phrase","シードフレーズ（リカバリーフレーズ）","シードフレーズとは、ウォレットの秘密鍵をすべて復元できる12語または24語の英単語の並びで、ウォレットのマスターキーにあたるものです。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"「儲けさせてあげる」と言う人がいたら、まず何を要求しているか見極めよう"},"coin":null,"tool":null,"cta":false},"hash-rate":{"slug":"hash-rate","cat":"onchain","en":"Hash rate","contentLocale":"ja","term":"ハッシュレート","aka":["採掘速度","hash rate","ハッシュパワー"],"short":"ハッシュレートとは、プルーフ・オブ・ワーク（PoW）のブロックチェーンでマイニング機器が1秒間に計算できるハッシュの回数のことで、ネットワーク全体の計算力を表します。","body":[[["ビットコイン","bitcoin"],"の",["マイニング","mining"],"では、条件を満たすハッシュ値を見つけるために膨大な計算を繰り返します。その計算速度がハッシュレートで、単位はH/s（ハッシュ毎秒）です。ネットワーク全体では EH/s（エクサハッシュ毎秒、1秒間に10の18乗回）という単位で表されます。"],"ネットワーク全体のハッシュレートが高いほど、攻撃者が過半数の計算力を握って取引を書き換える「51%攻撃」が難しくなります。そのため、ハッシュレートはセキュリティの目安としてよく使われます。ビットコインでは約2週間（2,016ブロック）ごとに難易度が調整され、ハッシュレートが増えても平均約10分でブロックが生成されるように保たれます。",[["半減期","bitcoin-halving"],"で報酬が減ったり、電気代が上がったりすると、採算の合わないマイナーが停止してハッシュレートが一時的に下がることがあります。ただし、ハッシュレートと価格の関係は単純ではなく、どちらかがもう一方を確実に動かすわけではありません。"]],"example":"ネットワーク全体のハッシュレートが600 EH/sで、あなたのマイニング機器が200 TH/sだとします。1 EH/sは1,000,000 TH/sなので、全体は600,000,000 TH/sです。あなたのシェアは200÷600,000,000で約0.000033%です。1日に生成されるブロックは平均144個、報酬は1ブロック3.125 BTCなので1日の報酬は合計450 BTCです。手数料を除いた単純計算での期待値は、450 BTC×0.00000033で約0.00015 BTC、つまり約15,000 satsになります。","mistakes":["ハッシュレートが上がれば必ず価格も上がると考えてしまう。","マイニング機器の性能だけで収益を計算し、電気代やプール手数料を差し引かない。","ネットワーク全体のハッシュレートが増えると自分の取り分が減ることを考慮しない。"],"faq":[{"q":"ハッシュレートが下がると何が起きますか？","a":"一時的にブロック生成の間隔が長くなりますが、次の難易度調整で難易度が下がり、間隔は元に戻ります。大きく下がり続けるとセキュリティの面で懸念されます。"},{"q":"イーサリアムにハッシュレートはありますか？","a":"イーサリアムは2022年9月のThe Mergeでプルーフ・オブ・ステークに移行したため、現在はマイニングもハッシュレートもありません。"}],"title":"ハッシュレートとは？意味とマイニングとの関係","description":"ハッシュレートの意味と単位、ビットコインのセキュリティや難易度調整との関係、マイニング報酬の計算例をわかりやすく解説します。","related":[["mining","マイニング（採掘）","マイニング（採掘）とは、プルーフ・オブ・ワークのブロックチェーンで計算処理を行って取引をブロックにまとめ、その報酬として新規発行の暗号資産と手数料を受け取る活動です。"],["proof-of-work","プルーフ・オブ・ワーク（PoW）","プルーフ・オブ・ワーク（PoW）とは、マイナーが大量の計算で競争し、最初に条件を満たす答えを見つけた者が新しいブロックを追加できるコンセンサスの仕組みです。"],["bitcoin-halving","ビットコイン半減期","ビットコイン半減期とは、21万ブロックごと（約4年ごと）に、マイナーが受け取る新規発行のブロック報酬が半分になるイベントのことです。"],["on-chain-analysis","オンチェーン分析","オンチェーン分析とは、ブロックチェーン上に公開されている取引記録やアドレスの残高などのデータを集計し、資金の流れや市場参加者の行動を読み解く手法のことです。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"exchange-netflow":{"slug":"exchange-netflow","cat":"onchain","en":"Exchange inflows and outflows","contentLocale":"ja","term":"取引所ネットフロー（取引所への流入・流出）","aka":["取引所流入","取引所流出","ネットフロー","exchange netflow"],"short":"取引所ネットフローとは、一定期間に暗号資産取引所のウォレットへ入った量から出た量を差し引いた数値で、流入超か流出超かを示すオンチェーン指標です。","body":[["取引所への入金は、売却やデリバティブの証拠金に使う目的のことが多いため、大量の流入は売り圧力の増加と解釈されることがあります。逆に流出超は、個人",["ウォレット","crypto-wallet"],"での長期保管や、他の用途への移動を示していると見られることがあります。"],[["ステーブルコイン","stablecoin"],"の場合は解釈が逆になることが多く、取引所へのUSDTやUSDCの流入は「買うための資金が入ってきた」と読まれます。どの資産のフローなのかを必ず確認しましょう。"],["この指標の精度は、分析会社がどの",["アドレス","wallet-address"],"を取引所のものと特定しているかに左右されます。取引所内部のウォレット整理、カストディ業者への移動、ETFの資金移動などが大きな数字として現れることもあります。単発の数字ではなく、数日から数週間の傾向で見るのが一般的です。"]],"example":["ある日、取引所へのBTC流入量が12,000 ",["BTC","bitcoin"],"、流出量が9,000 BTCだったとします。ネットフローは12,000−9,000でプラス3,000 BTCとなり、流入超です。BTCが60,000ドルだとすると、約1億8,000万ドル分が取引所に入ったことになります。ただし、その流入のうち2,500 BTCがひとつのアドレスから一度に送られていて、それが取引所自身の別ウォレットだと判明した場合、実質的なネットフローは500 BTCにすぎません。数字の大きさだけでなく、内訳を見ることが重要です。"],"mistakes":["一日だけの大きな流入を見て、すぐに暴落が来ると判断してしまう。","BTCのフローとステーブルコインのフローで解釈が逆になることを忘れる。","取引所内部のウォレット移動やETF関連の移動を、個人投資家の売買と混同する。"],"faq":[{"q":"取引所からの流出は強気のサインですか？","a":"長期保管が増えていると解釈されることが多いですが、それだけで価格の方向は決まりません。他の指標や市場環境と合わせて判断する材料のひとつです。"},{"q":"取引所ネットフローのデータはどこで見られますか？","a":"オンチェーン分析サービスで確認できます。サービスによって取引所アドレスの特定方法が違うため、数値に差が出ることがあります。"}],"title":"取引所ネットフローとは？流入・流出の読み方","description":"取引所ネットフロー（流入・流出）の意味、BTCとステーブルコインで解釈が変わる理由、数字を読むときの落とし穴を解説します。","related":[["on-chain-analysis","オンチェーン分析","オンチェーン分析とは、ブロックチェーン上に公開されている取引記録やアドレスの残高などのデータを集計し、資金の流れや市場参加者の行動を読み解く手法のことです。"],["whale","クジラ（大口投資家）","クジラとは、特定の暗号資産を大量に保有し、その売買や送金が市場価格に影響を与えるほどの規模を持つ大口の投資家やアドレスのことです。"],["proof-of-reserves","準備金証明（プルーフ・オブ・リザーブ）","準備金証明（PoR）とは、取引所が利用者から預かった暗号資産と同額以上の資産を実際に保有していることを、ブロックチェーン上のデータなどで示す仕組みです。"],["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"active-addresses":{"slug":"active-addresses","cat":"onchain","en":"Active addresses","contentLocale":"ja","term":"アクティブアドレス数","aka":["アクティブアドレス","active addresses"],"short":"アクティブアドレス数とは、一定期間内に送金または受取の取引に関わったブロックチェーン上のアドレスの数で、ネットワークの利用状況を測るオンチェーン指標です。","body":[["たとえば「日次アクティブアドレス」は、その日に少なくとも1回、送信者か受信者として取引に登場したユニークな",["アドレス","wallet-address"],"の数です。アプリの「日間アクティブユーザー数」に近い考え方で、ネットワークがどれだけ使われているかの目安になります。"],["ただし、アドレス数は人数と一致しません。1人が多数のアドレスを使うこともあれば、取引所のように1つのアドレスで多くの利用者の資金を扱うこともあります。手数料の安いチェーンでは、",["エアドロップ","airdrop"],"目当てのボットが大量のアドレスを作って数字を膨らませることもあります。"],["そのため、アクティブアドレス数は取引件数、手数料収入、",["預かり資産","total-value-locked"],"（TVL）などと組み合わせて見るのが基本です。チェーンごとにアドレスの仕組みや手数料が違うので、異なるチェーンの数字を単純に比べることにも注意が必要です。"]],"example":["ある",["レイヤー2","layer-2"],"チェーンの日次アクティブアドレスが、1か月で100,000から400,000へ4倍に増えたとします。一見すると利用が急拡大したように見えます。しかし同じ期間の手数料収入が1日5,000ドルから5,500ドルと10%しか増えておらず、新しいアドレスの多くが0.001 ETH前後の同じ金額を送り合っているとわかった場合、エアドロップを狙った自動取引が増えただけの可能性があります。数字が4倍になったことと、実際の利用者が4倍になったことは別の話です。"],"mistakes":["アクティブアドレス数をそのまま利用者の人数だと考えてしまう。","手数料が極端に安いチェーンと高いチェーンのアドレス数を単純に比較する。","エアドロップ期待で一時的に増えた数字を、長期的な成長と誤解する。"],"faq":[{"q":"アクティブアドレス数が増えると価格は上がりますか？","a":"利用拡大の目安にはなりますが、価格との関係は一定ではありません。数字の中身や他の指標と合わせて判断する必要があります。"},{"q":"アクティブアドレス数はどう数えるのですか？","a":"一定期間に送信者または受信者として取引に登場したアドレスを重複なしで数えます。分析サービスによって定義が少し異なる場合があります。"}],"title":"アクティブアドレス数とは？意味と正しい見方","description":"アクティブアドレス数の意味と数え方、人数と一致しない理由、ボットやエアドロップによる水増しを見抜くポイントを解説します。","related":[["on-chain-analysis","オンチェーン分析","オンチェーン分析とは、ブロックチェーン上に公開されている取引記録やアドレスの残高などのデータを集計し、資金の流れや市場参加者の行動を読み解く手法のことです。"],["wallet-address","ウォレットアドレス","ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。"],["trading-volume","取引量（出来高）","取引量（出来高）とは、一定期間に実際に売買が成立した暗号資産の数量や金額の合計のことで、一般には24時間の値が使われます。"],["total-value-locked","TVL（預かり資産総額）","TVLとは、DeFiのプロトコルやブロックチェーンに預けられている暗号資産の総額をドルなどで表した指標で、利用規模の目安として使われます。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"fear-and-greed-index":{"slug":"fear-and-greed-index","cat":"onchain","en":"Fear and Greed Index","contentLocale":"ja","term":"恐怖・強欲指数（Fear and Greed Index）","aka":["恐怖強欲指数","Fear & Greed Index","センチメント指数"],"short":"恐怖・強欲指数とは、価格変動率や出来高、SNSの反応などを組み合わせて、市場参加者の心理を0（極度の恐怖）から100（極度の強欲）の数値で表した指標です。","body":[[["暗号資産","cryptocurrency"],"でよく参照されるのは、",["ビットコイン","bitcoin"],"を対象にした恐怖・強欲指数です。",["ボラティリティ","volatility"],"、",["出来高","trading-volume"],"と勢い、SNSでの言及、ビットコインのドミナンス、検索トレンドなどを組み合わせて計算されています。提供元によって構成要素や重み付けは異なります。"],["一般的には、0から24が「極度の恐怖」、75から100が「極度の強欲」と区分されます。極端な恐怖のときは投げ売りが出やすく、極端な強欲のときは高い",["レバレッジ","leverage"],"や",["資金調達率","funding-rate"],"の上昇など、過熱のサインが重なりやすい傾向があります。"],"この指数は「今、市場がどんな気分か」を数値にしたもので、売買のタイミングを教えてくれるものではありません。強欲の状態が何週間も続くこともあります。自分が周りの雰囲気に流されていないかを点検する道具として使うのが現実的です。"],"example":"ある週に指数が82（極度の強欲）を示し、同時に主要取引所の資金調達率が8時間あたり0.05%に上がっていたとします。これは1日で0.15%、年率に換算すると約55%で、ロングを持つためのコストがかなり高い状態です。あなたが10倍のレバレッジで1,000 USDTの証拠金を使い、10,000 USDT分のロングを持つと、1日の資金調達コストは約15 USDTです。数値の高さだけで売買を決めるのではなく、こうしたコストや清算価格を確認するきっかけにできます。","mistakes":["指数が「極度の恐怖」になったら必ず底値だと考えて、一度に全額を買ってしまう。","強欲の状態が長く続く可能性を考えず、早すぎるタイミングでショートしてしまう。","提供元によって計算方法が違うことを知らず、別のサイトの数値を比べてしまう。"],"faq":[{"q":"恐怖・強欲指数はどのくらいの頻度で更新されますか？","a":"代表的なビットコインの指数は1日1回更新されます。提供元によっては、より短い間隔で更新されるものもあります。"},{"q":"恐怖・強欲指数だけで売買してもよいですか？","a":"この指数は市場の心理を示すもので、売買のタイミングを示すものではありません。資金調達率、出来高、自分のリスク許容度などと合わせて考える必要があります。"}],"title":"恐怖・強欲指数とは？Fear and Greed Indexの見方","description":"恐怖・強欲指数（Fear and Greed Index）の意味、0から100の数値の読み方、計算に使われる要素と使うときの注意点を解説します。","related":[["fomo","FOMO（フォーモ）","FOMOとは「Fear Of Missing Out」の略で、値上がりに乗り遅れることへの不安から、冷静な判断をせずに買ってしまう心理のことです。"],["fud","FUD（ファッド）","FUDとは「Fear, Uncertainty and Doubt（恐怖・不確実性・疑念）」の略で、市場に不安を広げ、売りを誘うような情報や雰囲気のことです。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"],["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"referral-code":{"slug":"referral-code","cat":"exchange-features","en":"Referral code (fee rebate)","contentLocale":"ja","term":"紹介コード（手数料キャッシュバック）","aka":["招待コード","リファラルコード","紹介リンク","手数料リベート"],"short":"紹介コードとは、取引所の口座開設時に入力することで、紹介者と新規利用者の双方に手数料の割引やキャッシュバックなどの特典が付与される仕組みです。","body":["多くの取引所には紹介プログラムがあり、既存の利用者やパートナーに固有の紹介コードやリンクが発行されます。新規利用者がそのコードで登録すると、取引手数料の一部が割引やキャッシュバックとして戻ってきたり、紹介者に報酬が支払われたりします。","特典の内容は、取引手数料の一定割合の還元、登録時のボーナス、期間限定のキャンペーンなど、取引所やプログラムによってさまざまです。多くの場合、紹介コードは口座開設時にしか入力できず、後から追加できないので注意が必要です。","紹介コードを使うかどうかで取引手数料そのものが変わることはありませんが、還元を受けられれば実質的なコストが下がります。一方、公式サイトに似せた偽の登録ページに誘導される詐欺もあるので、ドメインが取引所の公式のものかを必ず確認しましょう。"],"example":["あなたが",["先物取引","futures-contract"],"で月に合計500,000 USDT分を取引し、",["テイカー手数料","maker-taker-fees"],"が0.05%だとします。1か月の手数料は500,000×0.0005で250 USDTです。もし紹介コード経由で手数料の20%が還元される条件だった場合、毎月50 USDTが戻り、実質的な手数料は200 USDTになります。1年間続ければ600 USDTの差です。還元率や対象となる取引の種類、還元の上限や期間は取引所とプログラムによって違うので、登録前に条件を確認しておきましょう。"],"mistakes":["口座を作った後で紹介コードを入力しようとして、追加できないことに気づく。","SNSで見つけた紹介リンクの飛び先が、公式ドメインかどうかを確認せずに登録する。","還元の対象が先物だけ、期間限定などの条件を読まずに、すべての取引で還元されると考える。"],"faq":[{"q":"紹介コードは後から入力できますか？","a":"多くの取引所では口座開設時にしか入力できません。後から追加できるかどうかは取引所ごとに異なるので、登録前に用意しておくのが確実です。"},{"q":"紹介コードを使うと取引手数料は高くなりますか？","a":"いいえ、紹介コードを使っても基本の手数料は変わりません。条件に応じて手数料の一部が還元されるため、実質的なコストは下がります。"}],"title":"紹介コードとは？取引所の手数料還元の仕組み","description":"取引所の紹介コード（招待コード）の意味、手数料キャッシュバックの仕組みと計算例、登録前に確認すべき条件と偽サイトへの注意点を解説します。","related":[["maker-taker-fees","メイカー手数料・テイカー手数料（Maker/Taker）","メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。"],["vip-tier","VIPランク（手数料ティア）","VIPランクとは、取引所が利用者の取引量や資産残高に応じて設定する段階的な会員区分で、ランクが上がるほど取引手数料が安くなる仕組みです。"],["centralized-exchange","中央集権型取引所（CEX）","中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。"]],"lesson":null,"coin":null,"tool":"/rates","cta":true},"tokenized-treasuries":{"slug":"tokenized-treasuries","cat":"tokenized-assets","en":"Tokenized treasuries","contentLocale":"ja","term":"トークン化国債","aka":["トークン化米国債","オンチェーン国債","tokenized treasuries"],"short":"トークン化国債とは、米国債などの国債や、国債で運用するファンドの持分をブロックチェーン上のトークンとして発行し、その利回りをオンチェーンで受け取れるようにしたものです。","body":["代表例には、BlackRockのBUIDLや、Ondo FinanceのOUSGやUSDYなどがあります。発行体は短期の米国債やそれに準じる資産で運用し、利回りはトークンの価格上昇や追加トークンの配布という形で保有者に還元されます。",[["ステーブルコイン","stablecoin"],"の多くは利息を保有者に払いませんが、トークン化国債は国債の利回りに近い収益を得られる点が特徴です。そのため、",["暗号資産","cryptocurrency"],"の企業やDAOの余剰資金の運用先として、またDeFiでの担保として使われるようになっています。"],"注意点は、多くの商品が適格投資家や特定の地域の居住者向けに限定され、購入や償還にKYCが必要なことです。利回りは金利の水準に連動して変わり、償還の受付時間や最低金額などの条件も商品ごとに異なります。"],"example":"あるトークン化国債の価格が1トークン＝1.00ドルで始まり、運用資産の利回りが年4.5%、運用手数料が年0.15%だとします。あなたが10,000ドル分、つまり10,000トークンを1年間保有すると、手数料を引いた実質利回りは約4.35%で、トークンの価格は約1.0435ドルに上がり、評価額は約10,435ドルになります。同じ10,000ドルを利息のつかないステーブルコインで持っていれば10,000ドルのままです。ただし金利が下がれば利回りも下がり、償還に1営業日以上かかる商品もあります。","mistakes":["トークン化国債をステーブルコインと同じように、誰でもすぐに買えて1ドルで固定されていると考える。","利回りが固定だと思い込み、金利の変動で収益が変わることを見落とす。","償還の受付時間や最低金額を確認せず、急な換金ができずに困る。"],"faq":[{"q":"トークン化国債は誰でも買えますか？","a":"多くの商品は、本人確認を済ませた適格投資家や特定の地域の居住者に限定されています。一部には比較的広く購入できる商品もありますが、条件は発行体ごとに確認が必要です。"},{"q":"トークン化国債とステーブルコインの違いは何ですか？","a":"どちらも国債などを裏付けにすることがありますが、一般的なステーブルコインは利息を保有者に払いません。トークン化国債は国債の利回りを保有者に還元する点が違います。"}],"title":"トークン化国債とは？仕組みと利回りの受け取り方","description":"トークン化国債の意味と仕組み、BUIDLやOUSGなどの例、ステーブルコインとの違い、購入条件や償還などの注意点を解説します。","related":[["real-world-assets","RWA（現実資産のトークン化）","RWAとは、国債、株式、不動産、金、貸付債権など、ブロックチェーンの外にある現実の資産を、トークンとしてブロックチェーン上で表現したもの、またはその分野のことです。"],["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"],["apr-vs-apy","APRとAPYの違い（年利・年間利回り）","APRは複利を含まない単純な年利、APYは得た利息を再投資する複利効果を含めた年間利回りで、同じ金利でもAPYの方が高い数字になります。"],["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-treasuries","cta":false}});
